try{
  ClipboardPage Primary = tools.getPrimaryPage();
  ClipboardPage DataJSON = tools.findPage("temp");
  ClipboardPage SETJSON = tools.findPage("MyServicePage.ClaimData");
  String refNo = DataJSON.getProperty(".RefNo").toString();
  String claimNo = DataJSON.getProperty(".ClaimNo").toString();
  String notes = DataJSON.getProperty(".Remark").toString();
  String statusId = DataJSON.getProperty(".Status").toString();
  String approvedClaimAmount = DataJSON.getProperty(".ClaimAmount").toString();

  String Renew_json = "{\"refNo\":\""+refNo+"\","
    +"\"claimNo\":\""+claimNo+"\","
    +"\"notes\":\""+notes+"\","
    +"\"statusId\":\""+statusId+"\","
    +"\"approvedClaimAmount\":\""+approvedClaimAmount+"}";


  SETJSON.getProperty(".City").setValue(Renew_json);
} catch(Exception e){
  oLog.error("ReloadSection:Expection : "+e.getMessage());
}

